import { cacheTag } from 'next/cache'

export type Post = {
  id: number
  title: string
  content: string
  createdAt: number
}

// Simple in-memory backing store for the demo. In a real app this would be a
// database call.
const posts: Post[] = [
  {
    id: 1,
    title: 'Welcome to the posts demo',
    content: 'This list is cached with a "posts" cache tag.',
    createdAt: Date.now(),
  },
]

let nextId = 2

/**
 * Returns all posts, newest first. The result is cached via the "use cache"
 * directive and associated with the "posts" cache tag so it can be invalidated
 * on-demand when a new post is created.
 */
export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return [...posts].reverse()
}

/**
 * Persists a new post to the backing store. Callers are responsible for
 * invalidating the "posts" cache tag afterwards.
 */
export async function addPost(title: string, content: string): Promise<Post> {
  const post: Post = {
    id: nextId++,
    title,
    content,
    createdAt: Date.now(),
  }
  posts.push(post)
  return post
}

