'use server'

import { updateTag } from 'next/cache'
import { addPost } from '@/lib/posts'

export async function createPost(formData: FormData) {
  const title = (formData.get('title') as string | null)?.trim() ?? ''
  const content = (formData.get('content') as string | null)?.trim() ?? ''

  if (!title) {
    throw new Error('Title is required')
  }

  await addPost(title, content)

  // Invalidate the "posts" cache tag with read-your-own-writes semantics.
  //
  // `updateTag` (only callable from a Server Action) uses immediate
  // expiration — it marks the route as having revalidated both static and
  // dynamic data, so the next page load blocks on fresh data instead of
  // serving stale cached content. This is intentionally NOT `revalidateTag`,
  // which is a stale-while-revalidate update that can serve the previous
  // (stale) value while regenerating in the background.
  updateTag('posts')
}

